public class StringIntConversion {
    public static void main(String[] args) {
        int primitive = Integer.parseInt("42");   // String -> int
        Integer wrapper = Integer.valueOf("42");   // String -> Integer

        try {
            Integer.parseInt("12abc");            // throws NumberFormatException
        } catch (NumberFormatException e) {
            System.out.println("Invalid number");
        }

        int number = 100;
        String s1 = String.valueOf(number);        // preferred
        String s2 = Integer.toString(number);      // also good
        int hex = Integer.parseInt("FF", 16);      // 255 (radix 16)
        System.out.println(primitive + wrapper + s1 + s2 + hex);
    }
}
