public class TypePromotionDemo {
    public static void main(String[] args) {
        byte b1 = 10, b2 = 20;
        // byte sum = b1 + b2;        // COMPILE ERROR: result is int
        byte sum = (byte) (b1 + b2);   // OK -> 30
        byte literal = 10 + 20;        // OK: compile-time constant fits in byte

        int i = 100; long l = 5000L;
        var mixed = i + l;             // long (int promoted to long)
        char ch = 'A';
        var charResult = ch + 1;       // int (66), not char
        System.out.println(sum + " " + literal + " " + mixed + " " + charResult);
    }
}
```

